protected int64 prepareTasksForSelectedItems()
{
    if (this.parmSiteId() != '')
    {
        Query       locQuery = queryRun.query();

        QueryBuildDataSource    inventTableDS =   locQuery.dataSourceTable(tableNum(InventTable));
        QueryBuildDataSource    bomVersionDS =   inventTableDS.addDatasource(tableNum(BOMVersion));
        QueryBuildDataSource    inventDimDS;

        bomVersionDS.joinMode(JoinMode::InnerJoin);
        bomVersionDS.addLink(fieldNum(InventTable,ItemID),fieldNum(BOMVersion,ItemId));

        bomVersionDS.addRange(fieldNum(BOMVersion,Active)).value(SysQuery::value(NoYes::yes));
        bomVersionDS.addRange(fieldNum(BOMVersion,Approved)).value(SysQuery::value(NoYes::Yes));

        inventDimDS = bomVersionDS.addDataSource(tableNum(InventDim));
        inventDimDS.joinMode(JoinMode::InnerJoin);
        inventDimDS.addLink(fieldNum(BOMVersion,InventDimId),fieldNum(InventDim,InventDimId));
        InventDimDs.addRange(fieldNum(InventDim,InventSiteId)).value(this.parmSiteId());


    }
    int64       taskItems;
    taskItems = next prepareTasksForSelectedItems();

    return taskItems;
}
